// Interleaving keeps a person from answering nine near-identical trait prompts in a row.
export const questions=Array.from({length:9},(_,i)=>groups.map(g=>g[i])).flat();
export const agreement=['Strongly disagree','Disagree','Neither agree nor disagree','Agree','Strongly agree'];
export function scoreAnswers(answers){
 if(!Array.isArray(answers)||answers.length!==questions.length||Array.from(answers).some(a=>!Number.isInteger(a)||a<0||a>4))throw new Error('Please answer all 45 questions.');
 const sums=traits.map(()=>0),counts=traits.map(()=>0);
 questions.forEach((q,i)=>{sums[q.dim]+=q.reverse?4-answers[i]:answers[i];counts[q.dim]++});
 return sums.map((n,i)=>Math.round(n/(counts[i]*4)*100));
}
export const band=score=>score<40?0:score>60?2:1;
export function profileFor(scores){
 if(!Array.isArray(scores)||scores.length!==5||scores.some(s=>!Number.isFinite(s)||s<0||s>100))throw new Error('Invalid profile.');
 const ranked=scores.map((s,i)=>({i,distance:Math.abs(s-50)})).sort((a,b)=>b.distance-a.distance||a.i-b.i);
 const i=ranked[0].i;
 return ranked[0].distance<=10?{title:'A balanced mix of preferences',summary:'Your answers sit near the middle across these five dimensions. Your preferences may depend on the situation and the people around you.'}:{title:traits[i].profiles[band(scores[i])].title,summary:traits[i].profiles[band(scores[i])].meaning};
}
export function validDraft(d){return !!d&&d.version===VERSION&&Array.isArray(d.answers)&&d.answers.length===45&&Array.from(d.answers).every(a=>a===null||(Number.isInteger(a)&&a>=0&&a<=4))&&Number.isInteger(d.index)&&d.index>=0&&d.index<45;}
